typedef enum tagAvr_Selection
{
	AVR_CONST_MODE = 0, /* Description: AVR constant reference voltage mode. The regulation will decouple with instantaneous dc-bus voltage. */
	AVR_LPF_MODE = 1, /* Description: AVR LPF reference voltage mode. The regulation will use dc-bus voltage which is low-pass filtered. */
	AVR_INST_MODE = 2 /* Description: AVR INST reference voltage mode. The regulation will use instantaneous dc-bus voltage. */
} emAVR_SELECTION; /* Description: Automatic Voltage Regulation method selection */

typedef enum tagDaxis_Cur_Ctrl
{
	NORMAL_FLUXWKN = 0, /* Description: D-axis current reference with normal wlux weakening process. */
	EXP_CUR_SPM = 1, /* Description: D-axis current reference with positive exponential-decay offset. */
	EXP_CUR_IPM = 2, /* Description: D-axis current reference with negtive exponential-decay offset. */
	DIRECT_CUR_REF = 3, /* Description: D-axis current reference assigned by external command. */
	FLUXWKN_INDUCT_EST = 4, /* Description: Flux weakening function use online inductor estimation result. */
	MTPV_SPM = 8, /* Description: MTPVunder SPM mode. */
	MTPV_ENABLE = 16, /* Description: MTPV enable. */
	MTPV_INDUCT_EST = 32, /* Description: MTPV function use online inductor estimation result. */
	MTPA_ENABLE = 64, /* Description: MTPA enable. */
	MTPA_INDUCT_EST = 128 /* Description: MTPA function use online inductor estimation result. */
} emDAXIS_CUR_CTRL; /* Description: Daxis current reference bitfield control flags. */

typedef enum tagDaxis_Cur_Status
{
	FLUX_WKN_OP = 0, /* Description: Motor under flux-weakening operation */
	MTPA_OP = 1, /* Description: Motor under maximum-torque-per-ampere operation */
	MTPV_OP = 2, /* Description: Motor under maximum-torque-per-voltage operation */
	EXT_REF_OP = 3 /* Description: Motor operated under external d-axis current reference. */
} emDAXIS_CUR_STATUS; /* Description: SM d-axis current reference status definition */

typedef enum tagDbc_Selection
{
	DBC_INST_TRAPZ = 0, /* Description: Trapezoidal curve based dead-time compensation which calculated by current magnitude. */
	DBC_ANGLE_TRAPZ = 1, /* Description: Trapezoidal curve based dead-time compensation which calculated by current angle. */
	DBC_INST_ARCTAN = 2, /* Description: Arctan curve based dead-time compensation. */
	DBC_INST_LUT = 3, /* Description: LUT-based dead-time compensation. */
	DBC_DISABLE = 4 /* Description: Disable compensation. */
} emDBC_SELECTION; /* Description: Dead-time compensation method selection */

typedef enum tagInertia_Est
{
	INERTIA_INIT_SET = 1, INERTIA_INIT_ACC = 2, INERTIA_GET_TORQ = 3, INERTIA_SECOND_ACC = 4, INERTIA_EST_END = 5, INERTIA_EST_FAIL = 6
} emINERTIA_EST; /* Description: Inertia estimation step enumeration */

