typedef enum tagSlsm_Ctrl_Status
{
	PG_MODE = 0, /* Description: FOC control with external position and speed feedback. This mode SHOULD NOT switch to HFI mode. */
	IF_MODE = 1, /* Description: Constant current control mode. This mode SHOULD NOT switch to HFI mode. */
	HFI_MODE = 2, /* Description: FOC control with high frequency injection based speed and position estimator. */
	FOB_MODE = 3, /* Description: FOC control with flux observer based speed and position estimator. */
	FOB_MODE_HFINJ = 4 /* Description: FOC control with flux observer based speed and position estimator. And injecting high frequency to get ready to
	 enter HFI mode. */
} emSLSM_CTRL_STATUS; /* Description: Synchronous motor FOC sensorlesss control mode status */

typedef enum tagVf_Curve
{
	POLYLINE_TRIPLE = 0, LINEAR_1P5TH = 1, LINEAR_2ND = 2, LINEAR_1ST = 3, POLYLINE_BOOSTED = 4
} emVF_CURVE; /* Description: VF table curve type. */

